/* @lc app=leetcode id=3552 lang=kotlin */ class Solution { fun minMoves(matrix: Array<String>): Int = matrix.size.let { m -> matrix[0].length.let { n -> (0 until m * n).filter { matrix[it / n][it % n] in 'A'..'Z' }.groupBy { matrix[it / n][it % n] }.let { pos -> IntArray(m * n) { Int.MAX_VALUE }.also { it[0] = 0 }.let { dist -> HashSet<Char>().let { used -> java.util.ArrayDeque<Int>().also { it.add(0) }.let { dq -> generateSequence { dq.pollFirst() }.forEach { u -> dist[u].let { d -> matrix[u / n][u % n].let { ch -> (if (ch in 'A'..'Z' && used.add(ch)) pos[ch]!!.filter { dist[it] > d }.forEach { v -> dist.set(v, d).also { dq.addFirst(v) } } else Unit).let { listOf(u / n + 1 to u % n, u / n - 1 to u % n, u / n to u % n + 1, u / n to u % n - 1).filter { (a, b) -> a in 0 until m && b in 0 until n && matrix[a][b] != '#' && dist[a * n + b] > d + 1 }.forEach { (a, b) -> dist.set(a * n + b, d + 1).also { dq.addLast(a * n + b) } } } } } }.let { dist[m * n - 1].let { if (it == Int.MAX_VALUE) -1 else it } } } } } } } } }